00144 function db_create_table($tablename, $fieldnames, $fieldattrib, $idfield = "id", $valarray = null)
00145 {
00146   global $g_lasttable;
00147 
00148   if ($tablename == null || $tablename == "")
00149     $tablename = $g_lasttable;
00150   $g_lasttable = $tablename;
00151 
00152   if (db_table_exists($tablename))
00153     return false;
00154 
00155   if (is_string($fieldnames))
00156     $fieldnames = preg_split("/[\r\n,]/", $fieldnames);
00157   if (is_string($fieldattrib))
00158     $fieldattrib = preg_split("/[\r\n,]/", $fieldattrib);
00159   $attribs = count($fieldattrib);
00160   if (count($fieldnames) != $attribs) {
00161     trigger_error(__FUNCTION__ . ": both arrays must be same length.");
00162     return false;
00163   }
00164   $sql = "CREATE TABLE " . APPPREFIX . "$tablename (";
00165   $sql .= "$idfield int(11) NOT NULL PRIMARY KEY ";
00166   if ($attribs != 0) {
00167     $sql .= ", ";
00168 
00169     for($i = 0; $i < $attribs; $i++)
00170     $sql .= $fieldnames[$i] . " " . $fieldattrib[$i] . ($i < $attribs - 1 ? ", " : "");
00171   }
00172   $sql .= ")";
00173   // Send the sql command
00174   $result = raw_db_query($sql);
00175   if (!$result) {
00176     trigger_error(__FUNCTION__ . ": could not create table $tablename.");
00177     return false;
00178   }
00179 
00180   if ($valarray)
00181     foreach($valarray as $values) {
00182     $result = db_create_record($tablename, $fieldnames, $values, $idfield);
00183     if ($result === false) {
00184       return false;
00185     }
00186   }
00187   return $result;
00188 }
