00304 function db_create_record($tablename, $fieldnames = null, $fieldvalues = null, $idfield = "id")
00305 {
00306   global $g_lasttable;
00307 
00308   if (!$tablename)
00309     $tablename = $g_lasttable;
00310   $g_lasttable = $tablename;
00311 
00312     if (!$fieldnames) {
00313       $fieldnames = db_list_table_fields($tablename);
00314       array_shift($fieldnames);
00315     }
00316     if (!$fieldvalues) {
00317       $fieldvalues = array_fill(0, count($fieldnames), 0);
00318 
00319     }
00320   // Get next available index
00321   $sql = "SELECT max($idfield) FROM " . APPPREFIX . $tablename;
00322   $result = raw_db_query($sql);
00323   if ($result === false) {
00324     return false;
00325   }
00326   $newid = (db_fetch_array($result, FETCH_NUM)) ;
00327   $newid = $newid[0] + 1;
00328   // Build the two arrays
00329   $names = is_string($fieldnames) ? preg_split("/[\r\n]/", $fieldnames) : $fieldnames;
00330   $values = is_string($fieldvalues) ? preg_split("/[\r\n]/", $fieldvalues) : $fieldvalues;
00331   if (count($names) != count($values)) {
00332     trigger_error(__FUNCTION__ . ": both arrays must be same length.\n");
00333     return false;
00334   }
00335   // Build the SQL query
00336   $nfields = count($names);
00337   $fieldnames = $names;
00338   $fieldvalues = $values;
00339   for($i = 0, $names = ""; $i < $nfields; $i++)
00340   $names .= $fieldnames[$i] . ($i < $nfields - 1 ? ", " : "");
00341   for($i = 0, $values = ""; $i < $nfields; $i++)
00342   $values .= "'" . db_escape_string($fieldvalues[$i]) . "'" . ($i < $nfields - 1 ? ", " : "");
00343 
00344   $sql = "INSERT INTO " . APPPREFIX . $tablename . " ($idfield, $names) VALUES ($newid, $values)";
00345 
00346   $result = raw_db_query($sql);
00347   if (!$result) {
00348     trigger_error(__FUNCTION__ . ": could not create new record in table $tablename.");
00349     return false;
00350   }
00351   return $newid;
00352 }
