00400 function db_edit_record($tablename, $id = 0, $fieldnames = null, $fieldvalues = null, $idfield = "id")
00401 {
00402   global $g_lasttable;
00403 
00404   if ($id == null || $id <= 0) { // Create a new record
00405     return db_create_record($tablename, $fieldnames, $fieldvalues, $idfield);
00406   } else { // Edit existing record
00407     if (!$tablename)
00408       $tablename = $g_lasttable;
00409     $g_lasttable = $tablename;
00410     // Build the two arrays
00411     if (!$fieldnames) {
00412       $fieldnames = db_list_table_fields($tablename);
00413       array_shift($fieldnames);
00414     }
00415     if (!$fieldvalues) {
00416       $fieldvalues = array_fill(0, count($fieldnames), 0);
00417 
00418     }
00419 
00420     $names = is_string($fieldnames) ? preg_split("/[\r\n]/", $fieldnames) : $fieldnames;
00421     $values = is_string($fieldvalues) ? preg_split("/[\r\n]/", $fieldvalues) : $fieldvalues;
00422 
00423     if (count($names) != count($values)) {
00424       trigger_error(__FUNCTION__ . ": both arrays must be same length.\n");
00425       return false;
00426     }
00427     // Build the SQL query
00428     $nfields = count($names);
00429     for($i = 0, $str = ""; $i < $nfields; $i++) {
00430       $str .= $names[$i] . "='" . db_escape_string($values[$i]) . "'" .
00431       ($i < $nfields - 1 ? ", " : "");
00432     }
00433 
00434     $sql = "UPDATE " . APPPREFIX . "$tablename SET $str WHERE $idfield=$id";
00435     // Send the SQL command
00436     $result = raw_db_query($sql);
00437     if (!$result) {
00438       trigger_error(__FUNCTION__ . ": could not edit record $id in table $tablename.");
00439       return false;
00440     }
00441     return $id;
00442   }
00443 }
