00457 function db_swap_records($tablename, $id1, $id2, $idfield = "id", $xchangeid = true)
00458 {
00459   global $g_lasttable;
00460   // Table name
00461   if (!$tablename)
00462     $tablename = $g_lasttable;
00463   $g_lasttable = $tablename;
00464   $table = APPPREFIX . "$tablename";
00465   // Build SQL strings
00466   $result = raw_db_query("SELECT * FROM $table WHERE $idfield = $id1");
00467   if (!$result) {
00468     trigger_error(__FUNCTION__ . ": could not read record $id1 in table $tablename.");
00469     return false;
00470   }
00471   $a = db_fetch_array($result, FETCH_ASSOC);
00472   $fieldvalues1 = array_values($a);
00473   $fieldnames1 = array_keys($a);
00474   array_shift($fieldvalues1);
00475   array_shift($fieldnames1);
00476 
00477   $result = raw_db_query("SELECT * FROM $table WHERE $idfield = $id2");
00478   if (!$result) {
00479     trigger_error(__FUNCTION__ . ": could not read record $id2 in table $tablename.");
00480     return false;
00481   }
00482   $a = db_fetch_array($result, FETCH_ASSOC);
00483   $fieldvalues2 = array_values($a);
00484   $fieldnames2 = array_keys($a);
00485   array_shift($fieldvalues2);
00486   array_shift($fieldnames2);
00487   // Exchange values
00488   if (db_edit_record($tablename, $id1, $fieldnames2, $fieldvalues2, $idfield) === false) return false;
00489   if (db_edit_record($tablename, $id2, $fieldnames1, $fieldvalues1, $idfield) === false) return false;
00490   // Exchange id's
00491   if ($xchangeid) {
00492     $unique = db_get_next_free_id($tablename);
00493     if (db_edit_record($tablename, $id1, array($idfield), array($unique), $idfield) === false) return false;
00494     if (db_edit_record($tablename, $id2, array($idfield), array($id1), $idfield) === false) return false;
00495     if (db_edit_record($tablename, $unique, array($idfield), array($id2), $idfield) === false) return false;
00496   }
00497   return true;
00498 }
