00535 function db_get_data($tablename, $id = null, $col = null, $where = "", $result_type = FETCH_NUM, $idfield = "id", $orderby = "")
00536 {
00537   global $g_lasttable;
00538 
00539   if (!$tablename)
00540     $tablename = $g_lasttable;
00541   $g_lasttable = $tablename;
00542 
00543   if (is_array($col))
00544     $col = implode(",", $col);
00545   if ($col === null || $col === "")
00546     $col = "*";
00547   // Build the WHERE clause
00548   if ($id !== null) {
00549     if (is_string($id) && strstr($id, ",")) {
00550       $id = explode(",", $id);
00551     }
00552     if (is_array($id)) {
00553       $idcond = "";
00554       for($i = 0; $i < count($id); $i++)
00555       $idcond .= "$idfield = '{$id[$i]}'" . ($i < count($id) - 1 ? " OR " : "");
00556     } else
00557       $idcond = "$idfield = '$id'";
00558 
00559     $condition = $where ? " WHERE ($where) AND ($idcond)" : " WHERE ($idcond)";
00560   } else
00561     $condition = $where ? " WHERE ($where)" : "";
00562 
00563   $orderby = $orderby ? " ORDER BY $orderby" : "";
00564   // Do the query
00565   $sql = "SELECT $col FROM " . APPPREFIX . $tablename . $condition . $orderby;
00566 
00567   $result = raw_db_query($sql);
00568   if (!$result)
00569     return false;
00570   // Loop to build the return array
00571   $array = array();
00572   while ($row = db_fetch_array($result, $result_type)) {
00573     if (count($row) == 1)
00574       $row = array_shift($row);
00575     $array[] = $row;
00576   }
00577   if (db_free_result($result) === false) return false;
00578   // Return the result
00579   if (!is_array($array))
00580     return $array;
00581 
00582   switch (count($array)) {
00583     case 0:
00584       return false;
00585 
00586     case 1:
00587 
00588       $test = $array; // Copy array
00589       $elem = array_shift($test); // 1st element of array...
00590       if (is_null($elem)) // ...is it null?
00591         return false; // Yes: return null
00592       if (is_scalar($elem)) // ...is it a scalar?
00593         return $elem; // Yes: return the element alone
00594       else
00595         return $array; // No: return the whole array
00596     default:
00597       return $array;
00598   }
00599 }
